// ===============================================================================
// DAEMIND SRE - PARSING DE DADOS DE CAMPANHA MULTICANAL
// ===============================================================================
const body = $json.body || $json;

const nomeCampanha = (body.nome_campanha || body.campaign_name || 'Lancamento_VIP_2026').trim().replace(/\s+/g, '_');
const tituloProduto = body.titulo_produto || body.product_name || 'Oferta Exclusiva';
const beneficios = body.beneficios || body.descricao || 'Alta qualidade, entrega rápida e garantia total.';
const precoPromocional = parseFloat(body.preco || body.price || 0);
const urlDestino = body.url_destino || body.target_url || 'https://minhaloja.com.br';
const orcamentoPlanejado = parseFloat(body.orcamento || body.budget || 500.00);

return [{
  json: {
    nome_campanha: nomeCampanha,
    titulo_produto: tituloProduto,
    beneficios: beneficios,
    preco_promocional: precoPromocional,
    url_destino: urlDestino,
    orcamento_planejado: orcamentoPlanejado
  }
}];

