// ===============================================================================
// DAEMIND SRE - PARSER DE RESPOSTA DO COPYWRITING IA
// ===============================================================================
const rawContent = $json.choices?.[0]?.message?.content || '{}';
let parsed = {};

try {
  const cleanJson = rawContent.replace(/```json\n?|```/g, '').trim();
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = {
    post_social_media: `Confira nosso lançamento: ${$('Sanitizar Dados da Campanha').item.json.titulo_produto}! Garanta já o seu.`,
    newsletter_assunto: `🔥 Novidade imperdível: ${$('Sanitizar Dados da Campanha').item.json.titulo_produto}`,
    newsletter_html: `<div style="font-family:sans-serif;padding:20px;"><h2>${$('Sanitizar Dados da Campanha').item.json.titulo_produto}</h2><p>${$('Sanitizar Dados da Campanha').item.json.beneficios}</p></div>`
  };
}

return [{
  json: {
    ...parsed,
    nome_campanha: $('Sanitizar Dados da Campanha').item.json.nome_campanha,
    url_destino: $('Sanitizar Dados da Campanha').item.json.url_destino,
    orcamento_planejado: $('Sanitizar Dados da Campanha').item.json.orcamento_planejado
  }
}];
